/// <summary>
/// PaffH 21.04.23
/// Filter Items with errors
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXProdIdent, FormCheckBoxErrorHandlingFilter), FormControlEventType::Clicked)
    , SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.')]
public static void FormCheckBoxErrorHandlingFilter_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun formRun = sender.formRun();
    if (formRun is NDXIProdIdentForm)
    {
        FormCheckBoxControl checkBox = sender as FormCheckBoxControl;
        NDXIProdIdentForm iProdIdentForm = formRun as NDXIProdIdentForm;
        iProdIdentForm.setFilterItemWithErrors(checkBox.value() == 1);
    }
}

