/// <summary>
/// PaffH 01.03.23
/// lookup BlockId's, not already assigned
/// </summary>
/// <param name = "_formReferenceControl">FormReferenceControl</param>
/// <param name = "_nDXProdIdentBlock2ItemId">NDXProdIdentBlock2ItemId</param>
/// <returns>NDXProdIdentBlockTable</returns>
static public NDXProdIdentBlockTable buildBlockIdControlLookup(FormReferenceControl _formReferenceControl, NDXProdIdentBlock2ItemId _nDXProdIdentBlock2ItemId)
{
    NDXProdIdentBlockTable selectedRecord;
    SysReferenceTableLookup sysTableLookup = SysReferenceTableLookup::newParameters(tableNum(NDXProdIdentBlockTable), _formReferenceControl, true);
    Query lookupQuery;

    sysTableLookup.addLookupfield(fieldNum(NDXProdIdentBlockTable, ID));
    sysTableLookup.addLookupfield(fieldNum(NDXProdIdentBlockTable, Name));

    lookupQuery = new Query();

    QueryBuildDataSource qbdsNDXProdIdentBlockTable = lookupQuery.addDataSource(tableNum(NDXProdIdentBlockTable));

    NDXHelperQueryRangeAdd nDXHelperQueryRangeAdd = NDXHelperQueryRangeAdd::construct(fieldId2Name(tableNum(NDXProdIdentBlockTable), fieldNum(NDXProdIdentBlockTable, ID)));
    NDXProdIdentBlock2ItemId nDXProdIdentBlock2ItemIdLocal;
    while select nDXProdIdentBlock2ItemIdLocal
        where nDXProdIdentBlock2ItemIdLocal.NDXProdIdentProcedureLine1 == _nDXProdIdentBlock2ItemId.NDXProdIdentProcedureLine1
            && nDXProdIdentBlock2ItemIdLocal.IDSort == _nDXProdIdentBlock2ItemId.IDSort
    {
        nDXHelperQueryRangeAdd.add(queryValue(NDXProdIdentBlockTable::findRecId(nDXProdIdentBlock2ItemIdLocal.NDXProdIdentBlockTable).ID), true);
    }
    if (nDXHelperQueryRangeAdd.elements())
    {
        qbdsNDXProdIdentBlockTable.addRange(fieldNum(NDXProdIdentBlockTable, ID)).value(nDXHelperQueryRangeAdd.RangeAsString());
    }

    sysTableLookup.parmQuery(lookupQuery);

    selectedRecord = sysTableLookup.performFormLookup();

    return selectedRecord;
}

