/// <summary>
/// PaffH 28.02.23
/// </summary>
/// <param name = "_formReferenceControl">FormReferenceControl</param>
/// <param name = "_nDXProdIdentProcedureLine2">NDXProdIdentProcedureLine2</param>
/// <returns>UnitOfMeasureConversion</returns>
static public UnitOfMeasureConversion buildUnitOfMeasureConversionControlLookup(FormReferenceControl _formReferenceControl, NDXProdIdentProcedureLine2 _nDXProdIdentProcedureLine2)
{
    UnitOfMeasureConversion selectedRecord;
    SysReferenceTableLookup sysTableLookup = SysReferenceTableLookup::newParameters(tableNum(UnitOfMeasureConversion), _formReferenceControl, true);
    Query lookupQuery;

    sysTableLookup.addLookupfield(fieldNum(UnitOfMeasureConversion, FromUnitOfMeasure));
    sysTableLookup.addLookupfield(fieldNum(UnitOfMeasureConversion, ToUnitOfMeasure));

    lookupQuery = new Query();

    QueryBuildDataSource qbdsUnitOfMeasureConversion = lookupQuery.addDataSource(tableNum(UnitOfMeasureConversion));
    qbdsUnitOfMeasureConversion.addRange(fieldNum(UnitOfMeasureConversion, Product)).value(queryValue(_nDXProdIdentProcedureLine2.inventTable().Product));

    sysTableLookup.parmQuery(lookupQuery);

    selectedRecord = sysTableLookup.performFormLookup();

    return selectedRecord;
}

/// <summary>
/// PaffH 28.02.23
/// lookup for route; filter routeVersion
/// </summary>
/// <param name = "_formReferenceControl">FormReferenceControl</param>
/// <param name = "_nDXProdIdentProcedureLine1">NDXProdIdentProcedureLine1</param>
/// <returns>Route</returns>
static public Route buildRouteControlLookup2(FormReferenceControl _formReferenceControl, NDXProdIdentProcedureLine1 _nDXProdIdentProcedureLine1)
{
    Route selectedRecord;
    SysReferenceTableLookup sysTableLookup = SysReferenceTableLookup::newParameters(tableNum(Route), _formReferenceControl, true);
    Query lookupQuery;

    sysTableLookup.addLookupfield(fieldNum(Route, RouteId));
    sysTableLookup.addLookupfield(fieldNum(Route, OprId));
    sysTableLookup.addLookupfield(fieldNum(Route, OprNum));
    sysTableLookup.addLookupfield(fieldNum(Route, OprPriority));

    lookupQuery = new Query();
    QueryBuildDataSource qbdsRoute = lookupQuery.addDataSource(tableNum(Route));
    QueryBuildDataSource qbdsRouteTable = qbdsRoute.addDataSource(tableNum(RouteTable));
    qbdsRouteTable.relations(true);
    qbdsRouteTable.fetchMode(QueryFetchMode::One2One);
    QueryBuildDataSource qbdsRouteVersion = qbdsRouteTable.addDataSource(tableNum(RouteVersion));
    qbdsRouteVersion.relations(true);
    qbdsRouteVersion.fetchMode(QueryFetchMode::One2One);
    qbdsRouteVersion.addRange(fieldNum(RouteVersion, RecId)).value(queryValue(RouteVersion::findRecId(_nDXProdIdentProcedureLine1.RouteVersion).RecId));

    sysTableLookup.parmQuery(lookupQuery);

    selectedRecord = sysTableLookup.performFormLookup();

    return selectedRecord;
}

/// <summary>
/// PaffH 18.07.22
/// </summary>
/// <param name = "_formReferenceControl">FormReferenceControl</param>
/// <param name = "_inventTable">InventTable</param>
/// <returns>Route</returns>
static public Route buildRouteControlLookup(FormReferenceControl _formReferenceControl, InventTable _inventTable)
{
    Route selectedRecord;
    SysReferenceTableLookup sysTableLookup = SysReferenceTableLookup::newParameters(tableNum(Route), _formReferenceControl, true);
    Query lookupQuery;

    sysTableLookup.addLookupfield(fieldNum(Route, RouteId));
    sysTableLookup.addLookupfield(fieldNum(Route, OprId));
    sysTableLookup.addLookupfield(fieldNum(Route, OprNum));
    sysTableLookup.addLookupfield(fieldNum(Route, OprPriority));

    lookupQuery = new Query();
    QueryBuildDataSource qbdsRoute = lookupQuery.addDataSource(tableNum(Route));
    QueryBuildDataSource qbdsRouteTable = qbdsRoute.addDataSource(tableNum(RouteTable));
    qbdsRouteTable.relations(true);
    qbdsRouteTable.fetchMode(QueryFetchMode::One2One);
    QueryBuildDataSource qbdsRouteVersion = qbdsRouteTable.addDataSource(tableNum(RouteVersion));
    qbdsRouteVersion.relations(true);
    qbdsRouteVersion.fetchMode(QueryFetchMode::One2One);
    qbdsRouteVersion.addRange(fieldNum(RouteVersion, ItemId)).value(queryValue(_inventTable.ItemId));
    //qbdsRouteVersion.addRange(fieldNum(RouteVersion,Active)).value(queryValue(NoYes::Yes));

    sysTableLookup.parmQuery(lookupQuery);

    selectedRecord = sysTableLookup.performFormLookup();

    return selectedRecord;
}

